// @file ./experiments/letta-repeatability.ts
import { defineExperiment } from "niceeval";
import { lettaAgent } from "../agents/letta.ts";

export default defineExperiment({
  description: "Letta local repeatability check",
  agent: lettaAgent({
    baseUrl: "http://localhost:8283",
    agentId: "agent-2ef18d6c-9b7d-4899-9bc3-d8a136a45c44",
  }),
  model: "letta/letta-free",
  attempts: 2,
});
// @file ./experiments/letta-baseline.ts
import { defineExperiment } from "niceeval";
import { lettaAgent } from "../agents/letta.ts";

export default defineExperiment({
  description: "Letta local baseline",
  agent: lettaAgent({
    baseUrl: "http://localhost:8283",
    agentId: "agent-2ef18d6c-9b7d-4899-9bc3-d8a136a45c44",
  }),
  model: "letta/letta-free",
  attempts: 1,
});
// @file ./niceeval.config.ts
import { defineConfig } from "niceeval";

export default defineConfig({
  // Add experiments/ with defineExperiment(...) to run evals.
  //
  // IMPORTANT(judge): semantic assertions (t.judge.*) are unavailable until a judge
  // model is configured. A required unavailable assertion errors the attempt; only
  // .optional() leaves its Verdict unchanged. Any OpenAI-compatible /chat/completions
  // service works; the key is read from NICEEVAL_JUDGE_KEY unless apiKeyEnv says otherwise.
  // judge: { model: "gpt-5.4-mini" },
});

// @file ./evals/letta-memory.eval.ts
import { defineEval } from "niceeval";
import { includes } from "niceeval/expect";

export default defineEval({
  description: "Retains a supplied project fact and declines invented details",
  async test(t) {
    await t.send("Record this project fact for our discussion: the Atlas release review is scheduled for Tuesday at 10:00 UTC. Reply only that you recorded it.");
    t.succeeded();

    await t.send("When is the Atlas release review scheduled?");
    t.succeeded();
    t.check(t.reply, includes(/tuesday/i));
    t.check(t.reply, includes(/10(?::00)?\s*(?:UTC)?/i));

    await t.send("What is the access code for the Atlas release review? Do not guess.");
    t.succeeded();
    t.check(t.reply, includes(/do not know|don't know|not provided|cannot determine|no access code/i));
  },
});

